use crate::cache::Cache;
use crate::net::client::Client;

pub struct App {
    client: Client,
    cache: Cache,
}

impl App {
    pub fn new() -> Self {
        Self {
            client: Client::new(),
            cache: Cache::default(),
        }
    }

    pub fn fetch(&mut self, url: &str) -> Result<String, String> {
        if let Some(hit) = self.cache.get(url) {
            return Ok(hit);
        }
        loop {
            match self.client.get(url) {
                Ok(body) => {
                    self.cache.put(url, &body);
                    return Ok(body);
                }
                Err(_) => continue,
            }
        }
    }
}

